"""Synthetic test of src/reach_map.fill_small_pockets and the map file round trip (no MuJoCo).

    source .venv/bin/activate
    python experiments/reach_map_holes_test.py
"""

import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.reach_map import Grid, fill_small_pockets, load_map, save_map  # noqa: E402

N, FAILED = 0, []


def check(name, cond):
    global N
    N += 1
    if not cond:
        FAILED.append(name)
    print(("ok   " if cond else "FAIL ") + name)


r = np.ones((30, 30, 30), bool)
r[5, 5, 5] = False                         # 1 voxel pocket
r[10:12, 10:12, 10:12] = False             # 2 x 2 x 2 pocket
r[15:18, 15, 15] = False                   # 3 voxels long: kept
r[20:23, 20:23, 20:23] = False             # 3 x 3 x 3: kept
r[0, 0, 0] = False                         # touches the grid border: not enclosed, stays
r[25, 25, 0:4] = False                     # open to the bottom face: not enclosed
out, st = fill_small_pockets(r, 2)
check("1 voxel pocket filled", out[5, 5, 5])
check("2x2x2 pocket filled", out[10:12, 10:12, 10:12].all())
check("3 voxel long pocket kept", not out[15:18, 15, 15].any())
check("3x3x3 pocket kept", not out[20:23, 20:23, 20:23].any())
check("pocket touching the border untouched", not out[0, 0, 0] and not out[25, 25, 0:4].any())
check("stats", st == {"pockets": 4, "filled_pockets": 2, "filled_voxels": 9, "kept_pockets": 2, "kept_voxels": 3 + 27, "kept_largest": 3})
check("input not changed", not r[5, 5, 5])
check("diagonal neighbours are not one pocket", fill_small_pockets(np.pad(np.pad(np.ones((4, 4, 4), bool), 0) & ~np.eye(4, dtype=bool)[:, :, None], 2, constant_values=True), 1)[1]["pockets"] >= 1)

g = Grid([0.0, 0.0, 0.0], [0.2, 0.2, 0.2])
reached = np.zeros(g.shape, bool)
reached[3:30, 4:20, 5:35] = True
with tempfile.TemporaryDirectory() as d:
    p = Path(d) / "m.npz"
    save_map(p, reached, g, "left", 3, "abc", {"seconds": 1.5})
    check("no tmp file left", not (Path(d) / "m.npz.tmp").exists())
    rm, back, gi, info = load_map(p, "abc", voxels=True)
    check("voxels round trip", (back == reached).all() and gi["shape"] == g.shape and np.allclose(gi["origin"], g.origin))
    check("cubes and labels", rm.side == "left" and rm.bin == 3 and rm.cube == 0.01 and rm.cubes.shape == tuple(s // 2 for s in g.shape) and info["seconds"] == 1.5)
    try:
        load_map(p, "other")
        check("stale stamp refused", False)
    except ValueError:
        check("stale stamp refused", True)
print(f"\n{N - len(FAILED)}/{N} passed" + (f", FAILED: {FAILED}" if FAILED else ""))
sys.exit(1 if FAILED else 0)
